using System;
using UnityEngine;

public static class EmbeddedArt
{
    const string ResearchLabPng = @"[... ELLIPSIZATION ...]";

    static Sprite researchLab;

    public static Sprite ResearchLab
    {
        get
        {
            if (researchLab) return researchLab;
            var tex = new Texture2D(2, 2, TextureFormat.RGBA32, false);
            tex.filterMode = FilterMode.Point;
            tex.wrapMode = TextureWrapMode.Clamp;
            tex.LoadImage(Convert.FromBase64String(ResearchLabPng));
            researchLab = Sprite.Create(tex, new Rect(0,0,tex.width,tex.height), new Vector2(.5f,.5f), 16f, 0, SpriteMeshType.FullRect);
            researchLab.name = "Embedded Research Lab";
            return researchLab;
        }
    }
}
